// Fully synthetic workbook builder: no original source rows, accounts or amounts.
import {zipSync,strToU8} from 'fflate';
import {capture,saved} from './own-payroll-run-synthetic.js';
import {uid} from './own-payroll-program-synthetic.js';
import {ownRunHash} from '../../lib/internal-own-payroll-run.js';
const esc=value=>String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
const cell=(ref,value,kind='text',formula=null)=>kind==='blank'?`<c r="${ref}"/>`:`<c r="${ref}"${kind==='text'?' t="inlineStr"':kind==='error'?' t="e"':''}>${formula===null?'':`<f>${esc(formula)}</f>`}${kind==='text'?`<is><t>${esc(value)}</t></is>`:`<v>${esc(value)}</v>`}</c>`;
const common={A1:'CAJAS ASISTENCIALES',A2:'OCTUBRE 2.026',A3:'CUENTA\nCONTABLE',B3:'CODIGOS',C3:'CONCEPTO'};
const profiles={general42and55:{I3:'CHEQUES',L3:'RETENIDO EN LA COOPARTICIPACION',D4:'JUR. 42',G4:'JUR. 55',J5:'TOTAL\nA DEPOSITAR',K5:'BANCO',D3:'LIQUIDACION',E4:'SUPLEMENTARIAS- BONO',E5:'JUR. 42',F5:'JUR. 55',H4:'TOTAL',I5:'IMPORTE A RETENER POR EL PROCESAM.'},jurisdiction42:{G3:'CHEQUES',E5:'JUR. 42',G5:'IMPORTE A RETENER POR EL PROCESAM.',K3:'RETENIDO EN LA COOPARTICIPACION',D4:'JUR. 42',H5:'A DEVOLVER',I5:'TOTAL A DEPOSITAR',J5:'BANCO',D3:'LIQUIDACION',E4:'SUPLEMENTARIAS- BONO',F4:'TOTAL'},jurisdiction55:{I3:'RETENIDO EN LA COOPARTICIPACION',D4:'JUR. 55',F4:'SALDOA FAVOR',G4:'TOTAL A DEPOSITAR',H5:'BANCO',E4:'SUPLEMENTARIAS',E5:'JUR. 55'}};
export function assistanceParts({profileIds=['general42and55','jurisdiction42','jurisdiction55'],amount='1.0000000000000000001',headerPatch={},period='OCTUBRE 2.026',extraCells=[],external=true}={}){
 const files={},sheets=[],rels=[];profileIds.forEach((id,n)=>{const number=n+1,headers={...common,...profiles[id],A2:period,...headerPatch},rows=new Map();for(const[ref,value]of Object.entries(headers)){const row=Number(ref.match(/\d+/)[0]);if(!rows.has(row))rows.set(row,[]);rows.get(row).push(cell(ref,value));}rows.set(6,[cell('A6','DEMO-CUENTA-A'),cell('B6','DEMO-CODIGO 100/120'),cell('C6','Entidad inventada sin efecto municipal'),cell('D6',amount,'number',external?'[1]Otra!A1':null)]);rows.set(7,[cell('C7','Dato no informado'),cell('D7','','blank')]);rows.set(8,[cell('C8','Subtotal inventado, no sumar automáticamente'),cell('D8','0','number','SUM(D6:D7)')]);rows.set(999,[cell('C999','Última fila sintética fuera de dimension'),cell('D999','0','number')]);for(const c of extraCells){const row=Number(c.ref.match(/\d+/)[0]);if(!rows.has(row))rows.set(row,[]);rows.get(row).push(cell(c.ref,c.value,c.kind??'number',c.formula??null));}const xml=`<?xml version="1.0"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><dimension ref="A1:L8"/><sheetData>${[...rows].sort((a,b)=>a[0]-b[0]).map(([r,c])=>`<row r="${r}">${c.join('')}</row>`).join('')}</sheetData></worksheet>`;files[`xl/worksheets/sheet${number}.xml`]=strToU8(xml);sheets.push(`<sheet name="DEMO ${id}" sheetId="${number}" r:id="rId${number}"/>`);rels.push(`<Relationship Id="rId${number}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${number}.xml"/>`);});
 files['xl/workbook.xml']=strToU8(`<?xml version="1.0"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>${sheets.join('')}</sheets></workbook>`);files['xl/_rels/workbook.xml.rels']=strToU8(`<?xml version="1.0"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">${rels.join('')}</Relationships>`);if(external)files['xl/externalLinks/externalLink1.xml']=strToU8('<externalLink><externalBook/></externalLink>');return files;
}
export const assistanceZip=options=>zipSync(assistanceParts(options));
export function assistanceCapture({capturedJurisdiction=true}={}){const c=capture();if(capturedJurisdiction)c.payload.sourceInventory.jurisdictions={version:'own-run-jurisdictions.v1',complete:true,total:c.payload.population.employees.length,rows:c.payload.population.employees.map((e,i)=>({contractId:e.contractId,employeeNumber:e.employeeNumber,registrationId:uid(400+i),identityToken:e.identityToken,jurisdictionCode:i%2===0?'42':'55'}))};c.payloadSha256=ownRunHash(c.payload);c.saved=saved(c);return c;}
